export default function next({ items, previous }) {
  if (!Array.isArray(items)) throw Error("Invalid grant list");
  const i = (previous?.i ?? -1) + 1,
    item = items[i];
  if (item && (!item.id || !item.title)) throw Error("Grant is missing ID or title");
  return { state: { i }, more: !!item, id: String(item?.id ?? "") };
}

