export default function row({ id, detail, analysis }) {
  if (!detail || String(detail.id) !== id || !detail.synopsis) throw Error("Grant detail mismatch");
  if (
    !analysis ||
    typeof analysis.goal !== "string" ||
    !Array.isArray(analysis.eligibility_matches)
  )
    throw Error("Invalid model result");
  const s = detail.synopsis,
    number = (x) => (x == null || x === "" ? null : Number.isFinite(Number(x)) ? Number(x) : null),
    date = (x) => {
      if (!x) return null;
      const t = Date.parse(x);
      if (!Number.isFinite(t)) throw Error("Invalid grant date");
      return new Date(t).toISOString();
    };
  return {
    records: [
      {
        fields: {
          "Opportunity Number": detail.opportunityNumber,
          Title: detail.opportunityTitle,
          URL: "https://www.grants.gov/search-results-detail/" + encodeURIComponent(id),
          Agency: s.agencyName ?? "",
          "Agency Email": s.agencyContactEmail ?? "",
          "Agency Phone": s.agencyContactPhone ?? "",
          "Posted Date": date(s.postingDate),
          "Response Date": date(s.responseDate),
          Funding: number(s.estimatedFunding),
          "Award Floor": number(s.awardFloor),
          "Award Ceiling": number(s.awardCeiling),
          Goal: analysis.goal,
          Notes: (analysis.good_to_know ?? []).join("\n"),
          "Success Criteria": (analysis.success_criteria ?? []).join("\n"),
          Duration: analysis.duration ?? "",
          "Eligibility?": analysis.eligibility_matches.length ? "Yes" : "No",
          "Eligibility Notes": analysis.eligibility_matches.join("\n"),
          Status: "New",
        },
      },
    ],
  };
}

