export default function mail({ grants }) {
  const esc = (s) =>
    String(s ?? "").replace(
      /[&<>"']/g,
      (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c],
    );
  if (!Array.isArray(grants)) throw Error("Invalid grants");
  return {
    has: grants.length > 0,
    html:
      "<h1>Latest AI Grants</h1>" +
      grants
        .map(({ fields: f }) => {
          const url = String(f.URL ?? "");
          if (!/^https:\/\/www\.grants\.gov\/search-results-detail\/\d+$/.test(url))
            throw Error("Invalid grant URL");
          return (
            "<h2>" +
            esc(f.Title) +
            "</h2><p>" +
            esc(f.Agency) +
            "</p><p>" +
            esc(f.Goal) +
            "</p><ul>" +
            String(f["Success Criteria"] ?? "")
              .split("\n")
              .map((x) => "<li>" + esc(x) + "</li>")
              .join("") +
            "</ul><p>Posted: " +
            esc(f["Posted Date"]) +
            "; Respond by: " +
            esc(f["Response Date"]) +
            '</p><p><a href="' +
            esc(url) +
            '">See details</a></p>'
          );
        })
        .join(""),
  };
}

