export default async function reserve({ id, scheduledAt }, ctx) {
  const day = scheduledAt.slice(0, 10);
  if (!id || !/^\d{4}-\d\d-\d\d$/.test(day)) throw Error("Missing subscriber or schedule date");
  const key = "grant-digest:" + day + ":" + id,
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect Gmail before retrying");
  if (s?.status === "done") return { key, skip: true };
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false };
}

